<!doctype html><html><head><meta charset="utf-8"><style>body{color:#334155;font-family:DejaVu Sans,sans-serif}.brand{color:#3878F8;text-transform:uppercase}.total{color:#334155;font-size:28px;font-weight:bold}hr{border:0;border-top:1px solid #334155}</style></head><body><h1 class="brand">POLISTAFF RECEIPT</h1><p>Receipt No: <strong>{{ $transaction->receipt_number }}</strong></p><hr><p>Nama: {{ $transaction->user->name ?? '-' }}</p><p>Keterangan: {{ $transaction->description }}</p><p>Tarikh: {{ $transaction->transaction_date->format('d/m/Y') }}</p><p>Kaedah: {{ $transaction->payment_method ?? '-' }}</p><p class="total">RM {{ number_format((float)$transaction->amount,2) }}</p></body></html>
